<script setup>
import PhoneInput from '../../components/common/PhoneInput.vue'
import {inject as injectAdminConfirmation} from 'vue'
const {confirmAction}=injectAdminConfirmation('admin')
import OrderStatusBadge from '../../components/orders/OrderStatusBadge.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import {onBeforeRouteLeave} from 'vue-router'
import DomainFilters from '../../components/admin/DomainFilters.vue'
import {customerFilters,orderFilters} from '../../constants/domainFilters'
import {ref,reactive,watch,inject} from 'vue'
import {RouterLink} from 'vue-router'
import {customersApi,guestsApi} from '../../api/customers.api'
import {useAuthStore} from '../../stores/auth'
import {useServerList} from '../../composables/useServerList'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import {formatCurrency,formatDateTime} from '../../utils/formatters'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),{notify}=inject('admin'),tab=ref('customers'),selected=ref(null),detailTab=ref('profile'),detailPage=ref(1),detail=useApiState(),mutation=useApiMutation()
const customers=useServerList(customersApi,{active:'',has_orders:'',sort:'created_at',direction:'desc'}),guests=useServerList(guestsApi,{phone:''})
onBeforeRouteLeave(()=>!mutation.busy.value)
const orderParams=reactive({search:'',status:'',type:'',payment_status:'',date_from:'',date_to:'',per_page:20})
const cleanOrders=()=>Object.fromEntries(Object.entries(orderParams).filter(([,v])=>v!==''))
const list=()=>tab.value==='customers'?customers:guests
async function select(row){selected.value=row;detailTab.value=tab.value==='guests'?'orders':'profile';detailPage.value=1;await loadDetail()}
function loadDetail(){const row=selected.value;if(!row)return;return detail.run(signal=>tab.value==='guests'?guestsApi.orders({phone:row.phone,...cleanOrders(),page:detailPage.value},signal):detailTab.value==='profile'?customersApi.show(row.id):customersApi[detailTab.value](row.id,{...(detailTab.value==='orders'?cleanOrders():{}),page:detailPage.value},signal))}
async function active(row){if(!(await confirmAction((row.is_active?'إيقاف':'تفعيل')+' حساب '+row.name+'؟')))return;const result=await mutation.run(()=>customersApi.active(row.id,!row.is_active));if(result.ok){notify('تم تحديث حالة الحساب.');customers.load();if(selected.value?.id===row.id)loadDetail()}}
watch(tab,()=>{selected.value=null;detail.clear();list().search()});watch(detailTab,()=>{detailPage.value=1;loadDetail()});customers.load()
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>العملاء</h1><p class="muted">الحسابات المسجلة والعملاء الضيوف وطلباتهم</p></div></AdminPageHeader><nav class="module-tabs" aria-label="نوع العملاء"><button :aria-pressed="tab==='customers'" @click="tab='customers'">الحسابات المسجلة</button><button :aria-pressed="tab==='guests'" @click="tab='guests'">الضيوف</button></nav><section class="panel"><form class="toolbar" @submit.prevent="list().search"><input v-if="tab==='customers'" v-model="customers.filters.search" aria-label="بحث العملاء" type="search" maxlength="150" placeholder="الاسم أو الهاتف أو البريد"><PhoneInput v-else v-model="guests.filters.phone" aria-label="هاتف الضيف" pattern=".*" placeholder="05xxxxxxxx"/><select v-if="tab==='customers'" v-model="customers.filters.active" aria-label="حالة الحساب"><option value="">كل الحالات</option><option value="1">نشط</option><option value="0">متوقف</option></select><button class="button" :disabled="list().state.loading.value">بحث</button><DomainFilters @clear="customers.search()" v-if="tab==='customers'" :form="customers.filters" :fields="customerFilters" :busy="list().state.loading.value"/></form><ApiFeedback :loading="list().state.loading.value" :error="list().state.error.value" @retry="list().load"/><div v-if="list().state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>العميل</th><th>الهاتف</th><th>الطلبات</th><th>قيمة الطلبات المكتملة</th><th>آخر طلب</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="row in list().state.data.value.data" :key="row.id||row.phone"><td><div class="admin-cell-value">{{ row.name||row.latest_name }}</div></td><td><div class="admin-cell-value"><bdi>{{ row.phone }}</bdi></div></td><td><div class="admin-cell-value">{{ row.orders_count }}</div></td><td><div class="admin-cell-value">{{ formatCurrency(row.total_spent) }}</div></td><td><div class="admin-cell-value">{{ formatDateTime(row.last_order_at) }}</div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button class="row-button" :disabled="detail.loading.value" @click="select(row)">التفاصيل</button><button v-if="tab==='customers'&&auth.can(row.is_active?'customers.deactivate':'customers.activate')" class="row-button" :class="{danger:row.is_active}" :disabled="mutation.busy.value" @click="active(row)">{{ row.is_active?'إيقاف':'تفعيل' }}</button></div></div></td></tr></tbody></table><p v-if="!list().state.data.value.data.length" class="empty">لا توجد نتائج مطابقة.</p></div><ApiPagination :meta="list().state.data.value?.meta" :links="list().state.data.value?.links" :busy="list().state.loading.value" @page="list().changePage"/><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></section><section v-if="selected" class="panel customer-details"><div class="panel-head"><h2>{{ selected.name||selected.latest_name }}</h2><button type="button" class="row-button" :disabled="mutation.busy.value" @click="selected=null;detail.clear()">إغلاق التفاصيل</button></div><nav v-if="tab==='customers'" class="module-tabs" aria-label="تفاصيل العميل"><button v-for="[value,label] in [['profile','الملف'],['orders','الطلبات'],['addresses','العناوين']]" :key="value" :aria-pressed="detailTab===value" @click="detailTab=value">{{ label }}</button></nav><form v-if="detailTab==='orders'" @submit.prevent="detailPage=1;loadDetail()"><DomainFilters @clear="detailPage=1;loadDetail()" :form="orderParams" :fields="orderFilters" :busy="detail.loading.value"/><button class="row-button" :disabled="detail.loading.value">بحث الطلبات</button></form><ApiFeedback variant="detail" :loading="detail.loading.value" :error="detail.error.value" @retry="loadDetail"/><template v-if="detail.data.value"><dl v-if="detailTab==='profile'" class="order-facts"><dt>الاسم</dt><dd>{{ detail.data.value.name }}</dd><dt>البريد</dt><dd>{{ detail.data.value.email||'غير مسجل' }}</dd><dt>الهاتف موثّق</dt><dd>{{ detail.data.value.phone_verified?'نعم':'لا' }}</dd><dt>الحالة</dt><dd>{{ detail.data.value.is_active?'نشط':'متوقف' }}</dd><dt>الطلبات</dt><dd>{{ detail.data.value.statistics?.orders_count }}</dd></dl><div v-else class="table-wrap"><table v-admin-table v-if="detailTab==='orders'"><thead><tr><th>الطلب</th><th>الحالة</th><th>الإجمالي</th><th>التاريخ</th></tr></thead><tbody><tr v-for="row in detail.data.value.data" :key="row.id"><td><div class="admin-cell-value"><RouterLink v-if="auth.can('orders.view')" :to="'/admin/orders/'+row.id"><bdi>{{ row.order_number }}</bdi></RouterLink><bdi v-else>{{ row.order_number }}</bdi></div></td><td><div class="admin-cell-value"><OrderStatusBadge :status="row.status"/></div></td><td><div class="admin-cell-value">{{ formatCurrency(row.pricing?.total) }}</div></td><td><div class="admin-cell-value">{{ formatDateTime(row.placed_at) }}</div></td></tr></tbody></table><table v-admin-table v-else><thead><tr><th>العنوان</th><th>المستلم</th><th>المدينة والحي</th><th>الشارع</th></tr></thead><tbody><tr v-for="row in detail.data.value.data" :key="row.id"><td><div class="admin-cell-value">{{ row.label }}</div></td><td><div class="admin-cell-value">{{ row.recipient_name }}</div></td><td><div class="admin-cell-value">{{ row.city }}، {{ row.district }}</div></td><td><div class="admin-cell-value">{{ row.street }}</div></td></tr></tbody></table><p v-if="!detail.data.value.data.length" class="empty">لا توجد بيانات مسجلة.</p></div><ApiPagination v-if="detailTab!=='profile'" :meta="detail.data.value.meta" :links="detail.data.value.links" :busy="detail.loading.value" @page="detailPage=$event;loadDetail()"/></template></section></main></template>
